import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convtrans3d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 Kd,
    .param .u32 Kh,
    .param .u32 Kw,
    .param .u32 stride_d,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .s32 pad_d,
    .param .s32 pad_h,
    .param .s32 pad_w,
    .param .u32 dil_d,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 groups,
    .param .u32 has_bias,
    .param .u32 outD,
    .param .u32 outH,
    .param .u32 outW
)
{
    .reg .pred  p_exit, p0, p1, p2, p3, p4, p5, p6, p7, p_hasb;
    .reg .b32   r_idx, r_tmp, r_ow, r_oh, r_od, r_co, r_n;
    .reg .b32   r_outW, r_outH, r_outD, r_Cout, r_N;
    .reg .b32   r_W, r_H, r_D, r_Cin;
    .reg .b32   r_Kw, r_Kh, r_Kd;
    .reg .b32   r_sd, r_sh, r_sw;
    .reg .s32   r_pad_d, r_pad_h, r_pad_w;
    .reg .b32   r_dd, r_dh, r_dw;
    .reg .b32   r_groups, r_has_bias;
    .reg .b32   r_Cout_g, r_Cin_g, r_g, r_co_per, r_ci_start, r_ci_end;
    .reg .s32   r_id_nom, r_ih_nom, r_iw_nom, r_id, r_ih, r_iw;
    .reg .b32   r_kd, r_kh, r_kw;
    .reg .b32   r_ci;
    .reg .b32   r_zero, r_one;

    .reg .b64   x_base, w_base, b_base, y_base, addr, off64;

    .reg .f32   acc, xval, wval, bval;

    // Load params
    ld.param.u64  x_base,   [x_ptr];
    ld.param.u64  w_base,   [w_ptr];
    ld.param.u64  b_base,   [b_ptr];
    ld.param.u64  y_base,   [y_ptr];

    ld.param.u32  r_N,      [N];
    ld.param.u32  r_Cin,    [Cin];
    ld.param.u32  r_Cout,   [Cout];
    ld.param.u32  r_D,      [D];
    ld.param.u32  r_H,      [H];
    ld.param.u32  r_W,      [W];

    ld.param.u32  r_Kd,     [Kd];
    ld.param.u32  r_Kh,     [Kh];
    ld.param.u32  r_Kw,     [Kw];

    ld.param.u32  r_sd,     [stride_d];
    ld.param.u32  r_sh,     [stride_h];
    ld.param.u32  r_sw,     [stride_w];

    ld.param.s32  r_pad_d,  [pad_d];
    ld.param.s32  r_pad_h,  [pad_h];
    ld.param.s32  r_pad_w,  [pad_w];

    ld.param.u32  r_dd,     [dil_d];
    ld.param.u32  r_dh,     [dil_h];
    ld.param.u32  r_dw,     [dil_w];

    ld.param.u32  r_groups,   [groups];
    ld.param.u32  r_has_bias, [has_bias];

    ld.param.u32  r_outD,   [outD];
    ld.param.u32  r_outH,   [outH];
    ld.param.u32  r_outW,   [outW];

    mov.u32   r_zero, 0;
    mov.u32   r_one, 1;

    // Compute global linear thread index
    .reg .b32 r_bx, r_tx, r_bdx;
    mov.u32  r_tx, %tid.x;
    mov.u32  r_bx, %ctaid.x;
    mov.u32  r_bdx, %ntid.x;
    mad.lo.s32 r_idx, r_bx, r_bdx, r_tx;

    // total elements = N * Cout * outD * outH * outW
    .reg .b32 r_tot, r_tmp1, r_tmp2, r_tmp3;
    mul.lo.u32 r_tmp1, r_outH, r_outW;           // outH*outW
    mul.lo.u32 r_tmp2, r_outD, r_tmp1;           // outD*outH*outW
    mul.lo.u32 r_tmp3, r_Cout, r_tmp2;           // Cout*outD*outH*outW
    mul.lo.u32 r_tot,  r_N,    r_tmp3;           // N*Cout*outD*outH*outW

    setp.ge.u32 p_exit, r_idx, r_tot;
    @p_exit bra DONE;

    // Decode index into (n, co, od, oh, ow)
    // ow = idx % outW; t = idx / outW;
    .reg .b32 t0, q;
    rem.u32 r_ow, r_idx, r_outW;
    div.u32 t0,   r_idx, r_outW;

    rem.u32 r_oh, t0,    r_outH;
    div.u32 t0,   t0,    r_outH;

    rem.u32 r_od, t0,    r_outD;
    div.u32 t0,   t0,    r_outD;

    rem.u32 r_co, t0,    r_Cout;
    div.u32 r_n,  t0,    r_Cout;

    // acc = bias[co] or 0
    mov.f32 acc, 0f00000000;
    setp.ne.u32 p_hasb, r_has_bias, r_zero;
    @!p_hasb bra NO_BIAS_LOAD;
    setp.eq.u64 p0, b_base, 0;
    @p0 bra NO_BIAS_LOAD;
    mul.wide.u32 off64, r_co, 4;
    add.s64 addr, b_base, off64;
    ld.global.f32 acc, [addr];
NO_BIAS_LOAD:

    // Compute per-group sizes
    div.u32 r_Cout_g, r_Cout, r_groups;  // out channels per group
    div.u32 r_Cin_g,  r_Cin,  r_groups;  // in channels per group

    // g = co / Cout_g
    div.u32 r_g, r_co, r_Cout_g;
    // co_per = co - g*Cout_g
    .reg .b32 r_gCoutg;
    mul.lo.u32 r_gCoutg, r_g, r_Cout_g;
    sub.s32 r_co_per, r_co, r_gCoutg;

    // ci range
    mul.lo.u32 r_ci_start, r_g, r_Cin_g;
    add.s32    r_ci_end,   r_ci_start, r_Cin_g;

    // Precompute y index base factor for (n, co, od, oh, ow)
    // y_idx = ((((n * Cout + co)*outD + od)*outH + oh)*outW + ow)
    .reg .b32 y_idx;
    .reg .b32 tmpA, tmpB, tmpC, tmpD;
    mul.lo.u32 tmpA, r_n,   r_Cout;
    add.s32    tmpA, tmpA,  r_co;             // n*Cout + co
    mul.lo.u32 tmpB, tmpA,  r_outD;
    add.s32    tmpB, tmpB,  r_od;             // *outD + od
    mul.lo.u32 tmpC, tmpB,  r_outH;
    add.s32    tmpC, tmpC,  r_oh;             // *outH + oh
    mul.lo.u32 tmpD, tmpC,  r_outW;
    add.s32    y_idx, tmpD, r_ow;             // *outW + ow

    // Loop over ci
    mov.u32 r_ci, r_ci_start;
LOOP_CI:
    setp.ge.u32 p1, r_ci, r_ci_end;
    @p1 bra LOOP_CI_END;

    // kd loop
    mov.u32 r_kd, r_zero;
LOOP_KD:
    setp.ge.u32 p2, r_kd, r_Kd;
    @p2 bra LOOP_KD_END;

    // id_nom = (s32)od + pad_d - (s32)(kd * dil_d)
    .reg .s32 kd_mul_dil_d;
    mul.lo.u32 r_tmp, r_kd, r_dd;            // u32
    cvt.s32.u32 kd_mul_dil_d, r_tmp;
    // PTX requires explicit cvt
    .reg .s32 od_s32;
    cvt.s32.u32 od_s32, r_od;
    sub.s32 r_id_nom, od_s32, kd_mul_dil_d;
    add.s32 r_id_nom, r_id_nom, r_pad_d;

    // check divisibility by stride_d
    .reg .s32 rem_id;
    .reg .s32 sd_s32;
    cvt.s32.u32 sd_s32, r_sd;
    rem.s32 rem_id, r_id_nom, sd_s32;
    setp.ne.s32 p3, rem_id, 0;
    @p3 bra NEXT_KD; // not divisible, skip all kh/kw

    // id = id_nom / stride_d
    div.s32 r_id, r_id_nom, sd_s32;

    // bounds check id in [0, D)
    setp.lt.s32 p4, r_id, 0;
    @p4 bra NEXT_KD;
    .reg .s32 D_s32;
    cvt.s32.u32 D_s32, r_D;
    setp.ge.s32 p5, r_id, D_s32;
    @p5 bra NEXT_KD;

    // kh loop
    mov.u32 r_kh, r_zero;
LOOP_KH:
    setp.ge.u32 p6, r_kh, r_Kh;
    @p6 bra LOOP_KH_END;

    // ih_nom = (s32)oh + pad_h - (s32)(kh * dil_h)
    .reg .s32 kh_mul_dil_h, oh_s32;
    mul.lo.u32 r_tmp, r_kh, r_dh;
    cvt.s32.u32 kh_mul_dil_h, r_tmp;
    cvt.s32.u32 oh_s32, r_oh;
    sub.s32 r_ih_nom, oh_s32, kh_mul_dil_h;
    add.s32 r_ih_nom, r_ih_nom, r_pad_h;

    // check divisibility by stride_h
    .reg .s32 sh_s32, rem_ih;
    cvt.s32.u32 sh_s32, r_sh;
    rem.s32 rem_ih, r_ih_nom, sh_s32;
    setp.ne.s32 p0, rem_ih, 0;
    @p0 bra NEXT_KH;

    // ih = ih_nom / stride_h
    div.s32 r_ih, r_ih_nom, sh_s32;

    // bounds check ih in [0, H)
    .reg .s32 H_s32;
    cvt.s32.u32 H_s32, r_H;
    setp.lt.s32 p0, r_ih, 0;
    @p0 bra NEXT_KH;
    setp.ge.s32 p0, r_ih, H_s32;
    @p0 bra NEXT_KH;

    // kw loop
    mov.u32 r_kw, r_zero;
LOOP_KW:
    setp.ge.u32 p7, r_kw, r_Kw;
    @p7 bra LOOP_KW_END;

    // iw_nom = (s32)ow + pad_w - (s32)(kw * dil_w)
    .reg .s32 kw_mul_dil_w, ow_s32;
    mul.lo.u32 r_tmp, r_kw, r_dw;
    cvt.s32.u32 kw_mul_dil_w, r_tmp;
    cvt.s32.u32 ow_s32, r_ow;
    sub.s32 r_iw_nom, ow_s32, kw_mul_dil_w;
    add.s32 r_iw_nom, r_iw_nom, r_pad_w;

    // check divisibility by stride_w
    .reg .s32 sw_s32, rem_iw;
    cvt.s32.u32 sw_s32, r_sw;
    rem.s32 rem_iw, r_iw_nom, sw_s32;
    setp.ne.s32 p0, rem_iw, 0;
    @p0 bra NEXT_KW;

    // iw = iw_nom / stride_w
    div.s32 r_iw, r_iw_nom, sw_s32;

    // bounds check iw in [0, W)
    .reg .s32 W_s32;
    cvt.s32.u32 W_s32, r_W;
    setp.lt.s32 p0, r_iw, 0;
    @p0 bra NEXT_KW;
    setp.ge.s32 p0, r_iw, W_s32;
    @p0 bra NEXT_KW;

    // Compute and accumulate for this (ci, kd, kh, kw)
    // x index: ((((n * Cin + ci) * D + id) * H + ih) * W + iw)
    .reg .b32 x_idx, t1, t2, t3, t4;
    mul.lo.u32 t1, r_n,  r_Cin;
    add.s32    t1, t1,  r_ci;                 // n*Cin + ci
    mul.lo.u32 t2, t1,  r_D;
    cvt.u32.s32 t3, r_id;
    add.s32    t2, t2,  t3;                   // *D + id
    mul.lo.u32 t3, t2,  r_H;
    cvt.u32.s32 t4, r_ih;
    add.s32    t3, t3,  t4;                   // *H + ih
    mul.lo.u32 t4, t3,  r_W;
    cvt.u32.s32 x_idx, r_iw;
    add.s32    x_idx, t4, x_idx;              // *W + iw

    mul.wide.u32 off64, x_idx, 4;
    add.s64 addr, x_base, off64;
    ld.global.f32 xval, [addr];

    // w index: ((((ci * Cout_g + co_per) * Kd + kd) * Kh + kh) * Kw + kw)
    .reg .b32 w_idx, w_t1, w_t2, w_t3, w_t4, w_t5;
    mul.lo.u32 w_t1, r_ci,     r_Cout_g;
    add.s32    w_t1, w_t1,     r_co_per;        // ci*Cout_g + co_per
    mul.lo.u32 w_t2, w_t1,     r_Kd;
    add.s32    w_t2, w_t2,     r_kd;            // *Kd + kd
    mul.lo.u32 w_t3, w_t2,     r_Kh;
    add.s32    w_t3, w_t3,     r_kh;            // *Kh + kh
    mul.lo.u32 w_t4, w_t3,     r_Kw;
    add.s32    w_idx, w_t4,    r_kw;            // *Kw + kw

    mul.wide.u32 off64, w_idx, 4;
    add.s64 addr, w_base, off64;
    ld.global.f32 wval, [addr];

    // acc += xval * wval
    fma.rn.f32 acc, xval, wval, acc;

NEXT_KW:
    add.s32 r_kw, r_kw, 1;
    bra LOOP_KW;
LOOP_KW_END:

NEXT_KH:
    add.s32 r_kh, r_kh, 1;
    bra LOOP_KH;
LOOP_KH_END:

NEXT_KD:
    add.s32 r_kd, r_kd, 1;
    bra LOOP_KD;
LOOP_KD_END:

    // next ci
    add.s32 r_ci, r_ci, 1;
    bra LOOP_CI;
LOOP_CI_END:

    // Store acc to y
    mul.wide.u32 off64, y_idx, 4;
    add.s64 addr, y_base, off64;
    st.global.f32 [addr], acc;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans3d_kernel")

def _triple(v):
    if isinstance(v, (list, tuple)):
        if len(v) == 3:
            return int(v[0]), int(v[1]), int(v[2])
        elif len(v) == 1:
            v = v[0]
    v = int(v)
    return v, v, v

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, 
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        kd, kh, kw = _triple(kernel_size)
        sd, sh, sw = _triple(stride)
        pd, ph, pw = _triple(padding)
        opd, oph, opw = _triple(output_padding)
        dd, dh, dw = _triple(dilation)
        self.kernel_size = (kd, kh, kw)
        self.stride = (sd, sh, sw)
        self.padding = (pd, ph, pw)
        self.output_padding = (opd, oph, opw)
        self.dilation = (dd, dh, dw)
        self.groups = groups

        assert in_channels % groups == 0 and out_channels % groups == 0, "in/out channels must be divisible by groups"

        # Weight shape follows PyTorch ConvTranspose3d: (in_channels, out_channels // groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kd, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None

        # Initialize like PyTorch ConvTransposeNd
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        x = x.contiguous()
        n, cin, D, H, W = x.shape
        assert cin == self.in_channels

        kd, kh, kw = self.kernel_size
        sd, sh, sw = self.stride
        pd, ph, pw = self.padding
        opd, oph, opw = self.output_padding
        dd, dh, dw = self.dilation

        # Output dimensions per PyTorch formula
        outD = (D - 1) * sd - 2 * pd + dd * (kd - 1) + opd + 1
        outH = (H - 1) * sh - 2 * ph + dh * (kh - 1) + oph + 1
        outW = (W - 1) * sw - 2 * pw + dw * (kw - 1) + opw + 1

        device = x.device
        dtype = x.dtype

        w = self.weight
        if w.device != device or w.dtype != dtype:
            w = w.to(device=device, dtype=dtype, non_blocking=True).contiguous()
        else:
            w = w.contiguous()

        if self.bias is not None:
            b = self.bias
            if b.device != device or b.dtype != dtype:
                b = b.to(device=device, dtype=dtype, non_blocking=True).contiguous()
            else:
                b = b.contiguous()
        else:
            b = None

        y = torch.empty((n, self.out_channels, outD, outH, outW), device=device, dtype=dtype)

        total = n * self.out_channels * outD * outH * outW
        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        module = _get_ptx_module()
        args = [
            x,                           # x_ptr
            w,                           # w_ptr
            (b if b is not None else u64(0)),  # b_ptr (0 if None)
            y,                           # y_ptr
            u32(n),
            u32(self.in_channels),
            u32(self.out_channels),
            u32(D), u32(H), u32(W),
            u32(kd), u32(kh), u32(kw),
            u32(sd), u32(sh), u32(sw),
            i32(pd), i32(ph), i32(pw),
            u32(dd), u32(dh), u32(dw),
            u32(self.groups),
            u32(1 if b is not None else 0),
            u32(outD), u32(outH), u32(outW),
        ]

        module.launch(
            "convtrans3d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=args,
            shared_memory=0,
            stream=torch.cuda.current_stream(device),
        )

        return y

