import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convtrans3d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 Kd,
    .param .u32 Kh,
    .param .u32 Kw,
    .param .u32 stride_d,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .s32 pad_d,
    .param .s32 pad_h,
    .param .s32 pad_w,
    .param .u32 dil_d,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 groups,
    .param .u32 has_bias,
    .param .u32 outD,
    .param .u32 outH,
    .param .u32 outW
)
{
    .reg .pred  p_exit, p0, p1, p2, p3, p4, p5, p6, p7, p_hasb;
    .reg .b32   r_idx, r_tmp, r_ow, r_oh, r_od, r_co, r_n;
    .reg .b32   r_outW, r_outH, r_outD, r_Cout, r_N;
    .reg .b32   r_W, r_H, r_D, r_Cin;
    .reg .b32   r_Kw, r_Kh, r_Kd;
    .reg .b32   r_sd, r_sh, r_sw;
    .reg .s32   r_pad_d, r_pad_h, r_pad_w;
    .reg .b32   r_dd, r_dh, r_dw;
    .reg .b32   r_groups, r_has_bias;
    .reg .b32   r_Cout_g, r_Cin_g, r_g, r_co_per, r_ci_start, r_ci_end;
    .reg .s32   r_id_nom, r_ih_nom, r_iw_nom, r_id, r_ih, r_iw;
    .reg .b32   r_kd, r_kh, r_kw;
    .reg .b32   r_ci;
    .reg .b32   r_zero, r_one;

    .reg .b64   x_base, w_base, b_base, y_base, addr, off64;

    .reg .f32   acc, xval, wval, bval;

    // Load params
    ld.param.u64  x_base,   [x_ptr];
    ld.param.u64  w_base,   [w_ptr];
    ld.param.u64  b_base,   [b_ptr];
    ld.param.u64  y_base,   [y_ptr];

    ld.param.u32  r_N,      [N];
    ld.param.u32  r_Cin,    [Cin];
    ld.param.u32  r_Cout,   [Cout];
    ld.param.u32  r_D,      [D];
    ld.param.u32  r_H,      [H];
    ld.param.u32  r_W,      [W];

    ld.param.u32  r_Kd,     [Kd];
    ld.param.u32  r_Kh,     [Kh];
    ld.param.u32  r_Kw,     [Kw];

    ld.param.u32  r_sd,     [stride_d];
    ld.param.u32  r_sh,     [stride_h];
    ld.param.u32  r_sw,     [stride_w];

    ld.param.s32  r_pad_d,  [pad_d];
    ld.param.s32  r_pad_h,  [pad_h];
    ld.param.s32  r_pad_w,  [pad_w];

    ld.param.u32  r_dd,     [dil_d];
    ld.param.u32  r_dh,     [dil_h];
    ld.param.u32  r_dw,     [dil_w];

    ld.param.u32  r_groups,   [groups];
    ld.param.u32  r_has_bias, [has_bias];

    ld.param.u32  r_outD,   [outD];
    ld.param.u32  r_outH,   [outH];
    ld.param.u32  r_outW,   [outW];

    mov.u32   r_zero, 0;
    mov.u32   r_one, 1;

    // Compute global linear thread index
