LOOP_KW_END:

NEXT_KH:
    add.s32 r_kh, r_kh, 1;
    bra LOOP_KH;
LOOP_KH_END:

NEXT_KD:
    add.s32 r_kd, r_kd, 1;
    bra LOOP_KD;
LOOP_KD_END:

